/// Returns the input text with each character wrapped in an ANSI color code,\n/// cycling through a predefined palette. The result ends with a reset code.\npub fn rainbow(text: &str) -> String {\n    // Basic 6‑color palette (red, yellow, green, cyan, blue, magenta)\n    const COLORS: [&str; 6] = [\n        "\x1b[31m", // red\n        "\x1b[33m", // yellow\n        "\x1b[32m", // green\n        "\x1b[36m", // cyan\n        "\x1b[34m", // blue\n        "\x1b[35m", // magenta\n    ];\n    let reset = "\x1b[0m";\n\n    let mut out = String::new();\n    for (i, ch) in text.chars().enumerate() {\n        let color = COLORS[i % COLORS.len()];\n        out.push_str(color);\n        out.push(ch);\n    }\n    out.push_str(reset);\n    out\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn test_rainbow_basic() {\n        let input = "ABC";\n        let result = rainbow(input);\n        let expected = "\x1b[31mA\x1b[33mB\x1b[32mC\x1b[0m";\n        assert_eq!(result, expected);\n    }\n\n    #[test]\n    fn test_rainbow_cycle() {\n        let input = "ABCDEFG";\n        let result = rainbow(input);\n        let expected = "\x1b[31mA\x1b[33mB\x1b[32mC\x1b[36mD\x1b[34mE\x1b[35mF\x1b[31mG\x1b[0m";\n        assert_eq!(result, expected);\n    }\n}\n
